            arg_names = [get_type_name(arg) for arg in args]
            return f"Union[{', '.join(arg_names)}]"
        elif args:
            arg_names = [get_type_name(arg) for arg in args]
            return f"{origin_name}[{', '.join(arg_names)}]"
        return origin_name

    if hasattr(type_, "__name__"):
        # Handle regular classes and built-in types
        module = getattr(type_, "__module__", "")
        name = type_.__name__
        if module in ("builtins", "typing"):
            return name
        return f"{module}.{name}"

    # Fallback for other cases
    return str(type_)

